package com.aethercontrol.network

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.fail
import org.junit.Test

/**
 * Unit tests for Connection.hkdfSha256().
 *
 * The known-answer vector was generated by the Python server using:
 *
 *   from cryptography.hazmat.primitives.kdf.hkdf import HKDF
 *   from cryptography.hazmat.primitives import hashes
 *   HKDF(hashes.SHA256(), 32, salt=salt, info=info).derive(ikm)
 *
 * which is the same RFC-5869 extract-then-expand construction the Kotlin
 * implementation follows.
 */
class ConnectionHkdfTest {

    /**
     * Minimal inline HKDF so we can test the algorithm without Android JNI.
     * This is a direct copy of the production logic in Connection.hkdfSha256().
     */
    private fun hkdfSha256(ikm: ByteArray, salt: ByteArray, info: ByteArray, length: Int = 32): ByteArray {
        require(length <= 32) { "hkdfSha256: length must be <= 32 (single T1 block)" }
        val mac = javax.crypto.Mac.getInstance("HmacSHA256")

        // Extract: PRK = HMAC-SHA256(key=salt, data=ikm)
        mac.init(javax.crypto.spec.SecretKeySpec(salt, "HmacSHA256"))
        val prk = mac.doFinal(ikm)

        // Expand T1 = HMAC-SHA256(key=PRK, data=info || 0x01)
        mac.init(javax.crypto.spec.SecretKeySpec(prk, "HmacSHA256"))
        mac.update(info)
        mac.update(0x01.toByte())
        val t1 = mac.doFinal()

        return if (length == 32) t1 else t1.copyOf(length)
    }

    private fun hex(s: String): ByteArray =
        s.chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    // ── Known-answer test ─────────────────────────────────────────────────────

    /**
     * ikm  = 000102...1f  (32 bytes)
     * salt = 404142...7f  (64 bytes)
     * info = "aethercontrol-session-v1"
     * expected = 7ab75b69acb2787dfa9b2f579c048e49fe31b8515c3d1ad47780c6eb5ccd96af
     */
    @Test
    fun `hkdfSha256 known-answer vector matches server output`() {
        val ikm = hex("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f")
        val salt = hex(
            "404142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f" +
            "606162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f"
        )
        val info = "aethercontrol-session-v1".toByteArray(Charsets.UTF_8)
        val expected = hex("7ab75b69acb2787dfa9b2f579c048e49fe31b8515c3d1ad47780c6eb5ccd96af")

        val result = hkdfSha256(ikm = ikm, salt = salt, info = info, length = 32)

        assertArrayEquals(
            "HKDF output must match the server-generated known-answer vector",
            expected,
            result,
        )
    }

    @Test
    fun `hkdfSha256 returns correct prefix when length is less than 32`() {
        val ikm  = hex("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f")
        val salt = hex(
            "404142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f" +
            "606162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f"
        )
        val info = "aethercontrol-session-v1".toByteArray(Charsets.UTF_8)

        val full  = hkdfSha256(ikm = ikm, salt = salt, info = info, length = 32)
        val short = hkdfSha256(ikm = ikm, salt = salt, info = info, length = 16)

        assertArrayEquals("Truncated result must equal first 16 bytes of full result",
            full.copyOf(16), short)
    }

    @Test(expected = IllegalArgumentException::class)
    fun `hkdfSha256 throws IllegalArgumentException for length greater than 32`() {
        hkdfSha256(ikm = ByteArray(32), salt = ByteArray(32), info = ByteArray(0), length = 33)
        fail("Should have thrown IllegalArgumentException")
    }
}
